        formula: 'S + have/has been + V-ing',
        analogy: '完成式 vs 完成進行式的差別：I have read the book（我讀完了）vs I have been reading the book（我一直在讀，還沒讀完）。進行式多了「過程感」和「還在繼續」的意思！',
