    intro: '名詞子句就是「一整句話變成一個名詞」。你可以把一句話塞進主詞、受詞、補語的位置——就像把一段 YouTube 影片縮成一個截圖，那個截圖就是名詞子句。學會它，你的英文句子瞬間升級 🚀',
