        formula: 'That + S + V + 單數動詞（當主詞）\nS + V + (that) + S + V（當受詞，that 可省）\nS + be + that + S + V（當補語）\nthe fact/news/idea/belief + that + S + V（同位語）',
        analogy: '就像把「他很努力」打包成一個盒子：That he works hard（這件事）is obvious. 整個 that 子句對外就是一個名詞！',
