        formula: 'S + V + so + adj./adv. + that + S + V....（如此...以致於...，後無名詞）\nS + V + such + a(n) + adj. + N + that + S + V....（如此...的 N，後有名詞）\nS + V + so + many/much/few/little + N + that + S + V....（如此多/少 N，以致於...）',
        analogy: '判斷 so 還是 such 就像看飲料杯貼標籤：so 貼在形容詞和副詞上（so hot, so quickly），such 貼在名詞上（such a hot day）。看到名詞 → such；看到形容詞/副詞 → so。就這麼簡單 😂',
